onRoleReachedMoon = function()     game.pauseLogic()	if global.getBool("lvl52_b1") then dialog.setSkipEnabled(true) end		repeat			sound.play("51-1");		    if dialog.show("Level52-1", faceWunai) ==1 then break end			if dialog.show("Level52-2", faceZhoumei) ==1 then break end			if dialog.show("Level52-3", faceRenzhen) ==1 then break end			sound.play("50-2");			if dialog.show("Level52-4", facePutong) ==1 then break end		    if dialog.show("Level52-5", facePutong) ==1 then break end			if dialog.show("Level52-6", faceBujie) ==1 then break end			if dialog.show("Level52-7", facePutong) ==1 then break end			sound.play("60-1");			if dialog.show("Level52-8", faceBujie) ==1 then break end			global.setBool("lvl52_b1")		until true		dialog.setSkipEnabled(false)    game.success()end